function XUiLuckyTenant2PopupStageDetail:Update()
    if not self._Control then
        return
    end

    local data = self._Control:GetUiData().StageDetail
    if not data then
        return
    end

    -- 更新关卡名称：章节名·关卡名（stage 表 Name）
    local displayName = (data.ChapterName and data.ChapterName ~= "" and (data.ChapterName) or "") .. (data.Name or "")
    if self.RImgStageName then
        self.RImgStageName.text = displayName
    end

    -- 更新最佳回合数
    if self.TxtSchedule then
        self.TxtSchedule.text = tostring(data.BestRound or 0)
    end

    -- 更新最佳分数
    if self.TxtScore then
        self.TxtScore.text = tostring(data.BestScore or 0)
    end

    -- 更新MAX标记
    if self.Max then
        self.Max.gameObject:SetActiveEx(data.IsMax or false)
    end

    -- 更新任务数量
    if self.TxtRewardNum then
        self.TxtRewardNum.text = tostring(data.QuestAmount or 0)
    end

    -- 更新关卡描述：普通描述 / 完美通关描述（配置表 Desc、PerfectDesc）；为空时隐藏该文本和其父节点
    local descNormal = data.Desc and tostring(data.Desc):gsub("^%s*(.-)%s*$", "%1") or ""
    if self.TxtTargetNormal then
        self.TxtTargetNormal.text = descNormal
        local parent = self.TxtTargetNormal.transform and self.TxtTargetNormal.transform.parent
        if parent and parent.gameObject then
            parent.gameObject:SetActiveEx(descNormal ~= "")
        end
    end
    local descPerfect = data.PerfectDesc and tostring(data.PerfectDesc):gsub("^%s*(.-)%s*$", "%1") or ""
    if self.TxtTargetPerfect then
        self.TxtTargetPerfect.text = descPerfect
        local parent = self.TxtTargetPerfect.transform and self.TxtTargetPerfect.transform.parent
        if parent and parent.gameObject then
            parent.gameObject:SetActiveEx(descPerfect ~= "")
        end
    end

    -- 关1只显示 UiStage1，关2只显示 UiStage2，关3只显示 UiStage3（当前是第几关就只亮第几个）
    local stageIndexInChapter = data.StageIndexInChapter or 0
    local uiStages = { self.UiStage1, self.UiStage2, self.UiStage3 }
    for i = 1, 3 do
        if uiStages[i] then
            uiStages[i].gameObject:SetActiveEx(i == stageIndexInChapter)
        end
    end

    -- 更新羁绊列表
    self.DynamicTableNormal:SetDataSource(data.Bonds or {})
    self.DynamicTableNormal:ReloadDataSync(1)

    -- 更新开始按钮状态
    if data.IsPlaying then
        if self.BtnTongBlue then
            self.BtnTongBlue.gameObject:SetActiveEx(true)
        end
        if self.BtnTongBlue02 then
            self.BtnTongBlue02.gameObject:SetActiveEx(false)
        end
    else
        if self.BtnTongBlue then
            self.BtnTongBlue.gameObject:SetActiveEx(false)
        end
        if self.BtnTongBlue02 then
            self.BtnTongBlue02.gameObject:SetActiveEx(true)
        end
    end

    -- 更新空状态提示
    if self.TextEmpty then
        local bonds = data.Bonds or {}
        self.TextEmpty.gameObject:SetActiveEx(#bonds == 0)
    end
end

