---开始游戏
function XUiLuckyTenant2PopupStageDetail:OnBtnTongBlue02Click(eventData)
    if not self._StageId then
        return
    end

    -- 请求服务器开始游戏
    XMVCA.XLuckyTenant2:RequestStart(self._StageId, function(playingStage)
        self:Close()
        -- 服务器返回成功后打开游戏界面
        -- playingStage 包含恢复游戏所需的 record 数据
        local seed = XTime.GetServerNowTimestamp()
        local isFirstTimeEntering = true
        XLuaUiManager.Open("UiLuckyTenant2Game", self._StageId, seed, isFirstTimeEntering, playingStage)
    end)
end

function XUiLuckyTenant2PopupStageDetail:OnDynamicTableEvent(event, index, grid)
    if event == DYNAMIC_DELEGATE_EVENT.DYNAMIC_GRID_ATINDEX then
        ---@type XUiLuckyTenant2PopupStageDetailGrid
        local data = self.DynamicTableNormal:GetData(index)
        grid:Update(data)
    elseif event == DYNAMIC_DELEGATE_EVENT.DYNAMIC_GRID_TOUCHED then
        local data = self.DynamicTableNormal:GetData(index)
        if data and data.BondId then
            self:OpenBondDetail(data.BondId)
        end
    end
end

---打开羁绊详情
---@param bondId number 羁绊ID
function XUiLuckyTenant2PopupStageDetail:OpenBondDetail(bondId)
    if not self._BondsDetail or not self._Control then
        return
    end

    -- 从Control获取羁绊详情数据
    local bondData = self._Control:GetBondDetailDataForStagePopup(bondId)
    if not bondData then
        return
    end

    -- 打开羁绊详情面板
    self._BondsDetail:Open()
    self._BondsDetail:Update(bondData)
end

return XUiLuckyTenant2PopupStageDetail
